// Component
tasks = ['Learn Angular', 'Build an app', 'Deploy to production'];

// Template
<ul>
  <li *ngFor="let task of tasks">{{ task }}</li>
</ul>

// Component
tasks = [
  { id: 1, name: 'Learn Angular' },
  { id: 2, name: 'Build app' }
];
trackById(index: number, item: any) {
  return item.id;
}

// Template
<li *ngFor="let task of tasks; trackBy: trackById">
  {{ task.name }}
</li>
